package com.keyforge.nativeload;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class NativeWorkflowParserTest {private final NativeWorkflowParser p=new NativeWorkflowParser();@Test void parsesStaticApprovalGraphAndLineage(){var r=p.parse("{\"rows\":[{\"sourceId\":\"11111111111111111111111111111111\",\"name\":\"LCM\",\"definition\":{\"steps\":[{\"approval\":{\"owner\":\"Approvers\",\"ownerSource\":{\"rule\":\"DynamicOwner\"},\"children\":[]}}]},\"extractionRunId\":\"r1\"}]}").get(0);assertEquals("LCM",r.name);assertTrue(r.definition.contains("owner"));assertNotNull(r.hash);}@Test void rejectsErrorOrMissingRows(){assertThrows(NativeImportException.class,()->p.parse("{\"error\":{}}"));assertThrows(NativeImportException.class,()->p.parse("{\"ok\":true}"));}@Test void stableWorkflowUuid(){assertEquals(NativeWorkflowRepository.id("11111111111111111111111111111111"),NativeWorkflowRepository.id("11111111111111111111111111111111"));}}
